/* Fake llvm/Config/llvm-config.h for Pizlix (Fil-C).
 *
 * The real file is generated by LLVM's build; Fil-C never builds LLVM as a
 * library (the JIT shim statically links the in-tree LLVM 20.1.8 yolo).
 * mesa only needs the version gates from it: every `#if LLVM_VERSION_MAJOR
 * >= N` in gallivm/llvmpipe is a lower bound, and the curated
 * filc_llvm_jit.h surface corresponds to LLVM 20.1.8. */

#ifndef FILC_FAKE_LLVM_CONFIG_H
#define FILC_FAKE_LLVM_CONFIG_H

#define LLVM_VERSION_MAJOR 20
#define LLVM_VERSION_MINOR 1
#define LLVM_VERSION_PATCH 8
#define LLVM_VERSION_STRING "20.1.8"

/* The shim's LLVM is built with RTTI and EH off (matching -fno-rtti
 * -fno-exceptions); mesa's lone C++ file doesn't need either. */
#define LLVM_ENABLE_RTTI 0

#endif /* FILC_FAKE_LLVM_CONFIG_H */
